export const meta = {
  name: "draft_ideas_6_0_duffel_credit_audit",
  description: "Audits Duffel bookings for unused flight credits, vouchers, and refunds, builds an expiry tracker PDF, and returns a recoverable-dollars summary.",
  phases: [
    { name: "audit", detail: "Pull orders and build credit tracker" },
    { name: "verify", detail: "Confirm real Duffel data and deliverable" }
  ],
};

const AUDIT_SCHEMA = {
  type: "object",
  required: ["connected", "credits_found", "total_recoverable_usd", "summary", "tracker_pdf_path", "source_evidence"],
  properties: {
    connected: { type: "boolean" },
    credits_found: { type: "integer", minimum: 0 },
    total_recoverable_usd: { type: "number" },
    summary: { type: "string" },
    tracker_pdf_path: { type: ["string", "null"] },
    source_evidence: {
      type: "array",
      items: { type: "string" }
    },
    blocked_reason: { type: "string" },
    blocked_message: { type: "string" }
  },
  additionalProperties: true
};

const VERIFY_SCHEMA = {
  type: "object",
  required: ["approved", "retryable", "summary", "feedback", "blockers"],
  properties: {
    approved: { type: "boolean" },
    retryable: { type: "boolean" },
    summary: { type: "string" },
    feedback: { type: "string" },
    blockers: { type: "array", items: { type: "string" } }
  },
  additionalProperties: false
};

const MAX_ATTEMPTS = 2;
const THIRTY_MINUTES_MS = 30 * 60 * 1000;
const ONE_HOUR_MS = 60 * 60 * 1000;

function auditPrompt(inputs, feedback, previousOutput) {
  return `Audit Duffel bookings for unused flight credits.

Idea promise:
Scan Duffel bookings for unused flight credits, vouchers, change-fee refunds, and e-tickets with remaining value. Total what is recoverable, build an expiry tracker that alerts before anything lapses, and return a chat summary with dollars-at-risk.

Prerequisite context:
- Duffel is expected via Hatch's server-side broker, but verify live access. Do NOT assume it is connected.
- User-provided activation text (may be empty):
${JSON.stringify(inputs.ideaUserInput ?? "", null, 2)}

${feedback ? `Verifier feedback from previous attempt:
${feedback}

Repair the issue directly while preserving the idea promise.` : ""}

Tasks:
1. Verify Duffel access through available Hatch connectors / broker tools. If Duffel is NOT connected or returns no live API access, return connected=false with blocked_reason="missing_connection" and blocked_message="Connect Duffel in Account Center to run the credit audit.", do NOT fabricate data.
2. If connected, pull Duffel order history. Extract: ticket numbers, credit balances, voucher codes, PNRs, expiry dates, amounts, currency, and airline.
3. Identify unused credits, open vouchers, e-tickets with remaining value, and partial refunds. Compute total recoverable USD (convert if needed, note FX rate).
4. Build a credit expiry tracker PDF at workspace/your_files/duffel-credit-audit/credit-tracker.pdf
   - PDF style: warm editorial letter layout: full-page ivory paper, a centered reading column and dateline, an expressive handwritten-style title, a strong lead, readable serif body, restrained accent color, useful figures only when they help, and a compact signature. Avoid heavy report or dashboard chrome. Keep a consistent print-safe margin on every page, balance pagination, and prevent orphaned sections, clipping, or collisions. Render every page to an image and reject any page whose body, header, footer, signature, or page number touches the trim edge or overlaps other content.
   - Include: total recoverable, table of open credits (airline, PNR/ticket, amount, expiry, days_left), and 30/7-day alert note.
   - If zero credits found, produce a 1-page PDF confirming zero open credits and last scan date.
5. Do NOT create Markdown (.md) user-facing files. The PDF is the only user-facing file. Helper scripts, raw JSON, downloads, and verification images stay in the shared workflow working directory (exec commands start there). This overrides any skill/template defaults that colocate source beside the final file. workspace/your_files/duffel-credit-audit/ must contain only finished user-facing files.
6. Real-data requirement: use only real Duffel API data. Never substitute fake, sample, placeholder, generated, or synthetic values. Record source_evidence: order IDs, API call timestamps, or connector handles proving the data origin.
7. Optional: if credits with expiry are found, create a scheduled check that alerts 30/7 days before expiry (use native scheduler tools if available, otherwise note next_check_date in the PDF).

Return JSON matching AUDIT_SCHEMA:
- connected: boolean
- credits_found: integer
- total_recoverable_usd: number
- summary: concise chat-ready summary with total dollars at risk, count of credits, and nearest expiry
- tracker_pdf_path: "workspace/your_files/duffel-credit-audit/credit-tracker.pdf" or null if blocked
- source_evidence: array of strings proving real Duffel data origin
- if blocked: include blocked_reason and blocked_message

For chat-only or no-file cases, set tracker_pdf_path=null. Do not return source trees, build files, or intermediate files.`;
}

function verifyPrompt(auditResult, attempt) {
  return `Verify the Duffel Credit Audit output.

Attempt: ${attempt}

Audit result:
${JSON.stringify(auditResult, null, 2)}

Check:
1. If connected=false: verify blocked_reason=="missing_connection" and message asks to connect Duffel. That is an acceptable block, approve=false, retryable=false.
2. If connected=true:
   - Data is real Duffel data with source_evidence (order IDs, API timestamps). Reject any fabricated, sample, or synthetic values – that is non-retryable.
   - credits_found and total_recoverable_usd are consistent with the PDF tracker.
   - tracker_pdf_path exists at workspace/your_files/duffel-credit-audit/credit-tracker.pdf, is a finished PDF (not markdown), follows the warm editorial letter layout, margins safe, no clipping.
   - summary includes recoverable dollars total, credit count, and nearest expiry (or zero-credits confirmation).
   - No source/build/temp/verifier files are listed as deliverables.
3. Final handback can be a short curated chat message, not a dump.

Return JSON with approved, retryable, summary, feedback, blockers. Use retryable=true only when the audit agent can repair with your feedback. Fabricated data = retryable=false.`;
}

const inputs = args ?? {};

let feedback = "";
let auditResult = null;
let verified = null;

for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
  phase("audit");

  auditResult = await agent(auditPrompt(inputs, feedback, auditResult), {
    key: `audit-${attempt}`,
    label: attempt === 1 ? "Audit Duffel credits" : `Repair Duffel audit ${attempt}`,
    phase: "audit",
    timeoutMs: ONE_HOUR_MS,
    schema: AUDIT_SCHEMA,
  });

  if (!auditResult) {
    throw new Error("Audit agent failed to return structured output");
  }

  if (auditResult.connected === false) {
    return {
      __hatchWorkflowControl: "blocked",
      result: {
        blocked_reason: auditResult.blocked_reason || "missing_connection",
        message: auditResult.blocked_message || "Connect Duffel in Account Center to run the credit audit."
      }
    };
  }

  verified = await agent(verifyPrompt(auditResult, attempt), {
    key: `verify-${attempt}`,
    label: "Verify credit audit",
    phase: "verify",
    timeoutMs: THIRTY_MINUTES_MS,
    schema: VERIFY_SCHEMA,
  });

  if (verified.approved) {
    break;
  }
  if (!verified.retryable || attempt === MAX_ATTEMPTS) {
    break;
  }
  feedback = verified.feedback || verified.summary;
  log("Verifier requested repair", { attempt, feedback });
}

if (!verified || !verified.approved) {
  const message = verified && verified.blockers.length > 0
    ? verified.blockers.join("; ")
    : (verified ? verified.summary : "Verification did not produce a result.");
  return {
    __hatchWorkflowControl: "blocked",
    result: {
      blocked_reason: "verification_blocked",
      message,
    },
  };
}

const summaryText = auditResult.summary?.trim() || `Duffel credit audit complete: ${auditResult.credits_found} open credits, $${auditResult.total_recoverable_usd.toFixed(2)} recoverable.`;

const finalArtifacts = auditResult.tracker_pdf_path
  ? [{ type: "file", title: "Duffel Credit Tracker", path: auditResult.tracker_pdf_path, primary: true }]
  : [];

return {
  status: "completed",
  summary: summaryText,
  handback: finalArtifacts.length > 0
    ? { message: summaryText + "\n\nYour credit expiry tracker PDF is ready.", artifacts: finalArtifacts }
    : { message: summaryText },
};

